	local keybindDelta = 0;

	local function keybindObjects()
		local list = { KeybindPanel };
		for _, descendant in ipairs(KeybindPanel:GetDescendants()) do
			if descendant:IsA("GuiObject") then
				table.insert(list, descendant);
			end
		end
		return list;
